/* ------------------------------------------------------------------
   MNT STUDIO DANCE — Registre de présences
   Palette : scène plongée dans le noir + un unique projecteur.
   - fond quasi noir violine (#100D18)
   - surfaces (#1C1829)
   - accent projecteur : magenta (#FF3E7F)
   - accent second : or scène (#FFC857)
   Chaque site a sa propre couleur signature (comme sur le planning
   papier du studio) : Savigny = magenta, Moissy = vert, St Pierre = bleu.
   Typo : Bebas Neue (affichage, condensé, façon néon de studio)
          Inter (texte courant)
   Signature : la "barre" — un simple trait doré horizontal qui sépare
   les sections, comme la barre de danse classique.
------------------------------------------------------------------- */

const STORAGE_KEY = "mnt-studio-data-v2";
const uid = () => Math.random().toString(36).slice(2, 10);
const todayISO = () => new Date().toISOString().slice(0, 10);

const ADMIN_EMAIL = "contact@mntstudiodance.fr";

function buildAbsenceMailto(absence, teacher, course) {
  const dateStr = new Date(absence.date).toLocaleDateString("fr-FR", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });
  const signaledAt = new Date(absence.createdAt);
  const subject = `Absence professeur — ${teacher ? teacher.name : "Professeur"} — ${course ? course.name : "Cours"} — ${dateStr}`;
  const body = [
    "Un professeur a signalé une absence sur le registre MNT Studio Dance.",
    "",
    `Professeur : ${teacher ? teacher.name : "Inconnu"}`,
    `Cours concerné : ${course ? course.name : "Cours supprimé"}`,
    `Site : ${course ? `${course.site.replaceAll("-", " ")} — ${course.venue}` : "—"}`,
    `Date du cours : ${dateStr}`,
    `Motif : ${absence.reason || "Non précisé"}`,
    "",
    `Signalé le ${signaledAt.toLocaleDateString("fr-FR")} à ${signaledAt.toLocaleTimeString("fr-FR", {
      hour: "2-digit",
      minute: "2-digit",
    })}`,
  ].join("\n");
  return `mailto:${ADMIN_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

// Envoi automatique réel, sans backend et sans création de compte, via FormSubmit.co
// (service gratuit de relais d'email : la 1re fois, contact@mntstudiodance.fr recevra
// un email d'activation à confirmer d'un clic ; ensuite tout est 100% automatique).
async function sendAbsenceEmail(absence, teacher, course) {
  const dateStr = new Date(absence.date).toLocaleDateString("fr-FR", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });
  const signaledAt = new Date(absence.createdAt);
  const subject = `Absence professeur — ${teacher ? teacher.name : "Professeur"} — ${course ? course.name : "Cours"} — ${dateStr}`;
  const payload = {
    _subject: subject,
    _captcha: "false",
    _template: "table",
    Professeur: teacher ? teacher.name : "Inconnu",
    "Cours concerné": course ? course.name : "Cours supprimé",
    Site: course ? `${course.site.replaceAll("-", " ")} — ${course.venue}` : "—",
    "Date du cours": dateStr,
    Motif: absence.reason || "Non précisé",
    "Signalé le": `${signaledAt.toLocaleDateString("fr-FR")} à ${signaledAt.toLocaleTimeString("fr-FR", {
      hour: "2-digit",
      minute: "2-digit",
    })}`,
  };
  const res = await fetch(`https://formsubmit.co/ajax/${ADMIN_EMAIL}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error("Envoi automatique impossible");
  return res.json();
}
