function DossierBadge({ statut }) {
  const info = statutInfo(statut);
  return (
    <span
      className="inline-flex shrink-0 items-center gap-1.5 rounded-full border px-2 py-0.5 text-[11px]"
      style={{ borderColor: `${info.color}55`, color: info.color, backgroundColor: `${info.color}15` }}
    >
      <span className="h-1.5 w-1.5 rounded-full" style={{ backgroundColor: info.color }} />
      {info.label}
    </span>
  );
}

