function resolveImportCourseIds(courses, courseKeys) {
  const ids = [];
  const missing = [];
  courseKeys.forEach(([name, day]) => {
    const c = courses.find((c) => c.name === name && c.day === day);
    if (c) {
      if (!ids.includes(c.id)) ids.push(c.id);
    } else {
      missing.push(`${name} (${day})`);
    }
  });
  return { ids, missing };
}

function durationLabel(min) {
  if (!min || min === 60) return null;
  if (min === 90) return "1h30";
  if (min === 30) return "30 min";
  return `${min} min`;
}

function groupBySite(courses) {
  const groups = SITES.map((site) => ({ site, courses: courses.filter((c) => c.site === site) })).filter(
    (g) => g.courses.length
  );
  const others = courses.filter((c) => !SITES.includes(c.site));
  if (others.length) groups.push({ site: "Autres sites", courses: others });
  return groups;
}

// Un cours peut être assuré par plusieurs professeurs (ex. Afrobeat Junior le jeudi, co-animé
// par Adèle et Lowyzo). `teacherIds` est le champ de référence ; `teacherId` (ancien format,
// un seul professeur) reste supporté en lecture pour la compatibilité.
function courseTeacherIds(course) {
  if (course.teacherIds && course.teacherIds.length) return course.teacherIds;
  return course.teacherId ? [course.teacherId] : [];
}

function courseHasTeacher(course, teacherId) {
  return courseTeacherIds(course).includes(teacherId);
}

function courseTeacherNames(course, teachers) {
  const names = courseTeacherIds(course)
    .map((id) => teachers.find((t) => t.id === id))
    .filter(Boolean)
    .map((t) => t.name);
  return names.length ? names.join(" & ") : "Sans professeur";
}

function sortStudents(list) {
  return (list || []).slice().sort((a, b) => {
    const an = (a.nom || "").toLowerCase();
    const bn = (b.nom || "").toLowerCase();
    if (an !== bn) return an.localeCompare(bn, "fr");
    return (a.prenom || "").toLowerCase().localeCompare((b.prenom || "").toLowerCase(), "fr");
  });
}

function sortTeachers(list) {
  return (list || []).slice().sort((a, b) => (a.name || "").toLowerCase().localeCompare((b.name || "").toLowerCase(), "fr"));
}

