function schoolHolidayLabel(holidays, dateStr) {
  const h = (holidays || []).find((h) => dateStr >= h.start && dateStr <= h.end);
  return h ? h.label : null;
}

// Dimanche de Pâques (algorithme de Meeus/Jones/Butcher — calendrier grégorien).
function computeEasterSunday(year) {
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31);
  const day = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(year, month - 1, day);
}

function addDays(date, n) {
  const d = new Date(date);
  d.setDate(d.getDate() + n);
  return d;
}

// Les 11 jours fériés français, calculés automatiquement pour n'importe quelle année (aucune mise à jour nécessaire).
function frenchPublicHolidays(year) {
  const easter = computeEasterSunday(year);
  return [
    { label: "Jour de l'An", date: new Date(year, 0, 1) },
    { label: "Lundi de Pâques", date: addDays(easter, 1) },
    { label: "Fête du Travail", date: new Date(year, 4, 1) },
    { label: "Victoire 1945", date: new Date(year, 4, 8) },
    { label: "Ascension", date: addDays(easter, 39) },
    { label: "Lundi de Pentecôte", date: addDays(easter, 50) },
    { label: "Fête Nationale", date: new Date(year, 6, 14) },
    { label: "Assomption", date: new Date(year, 7, 15) },
    { label: "Toussaint", date: new Date(year, 10, 1) },
    { label: "Armistice 1918", date: new Date(year, 10, 11) },
    { label: "Noël", date: new Date(year, 11, 25) },
  ].map((h) => ({ label: h.label, dateStr: ymd(h.date) }));
}

function publicHolidayLabel(dateStr) {
  const year = Number(dateStr.slice(0, 4));
  const h = frenchPublicHolidays(year).find((h) => h.dateStr === dateStr);
  return h ? h.label : null;
}

function rateForCourse(teacher, course) {
  const th = Number(teacher.tarifHeure) || 0;
  const thd = Number(teacher.tarifHeureEtDemi) || 0;
  if (course.duration === 90) return thd;
  if (course.duration === 30) return th / 2;
  return th;
}

// Calcule le détail de paie d'un professeur pour un mois donné.
function computeTeacherPayroll(data, teacher, year, month) {
  const weeks = getMonthWeeks(year, month);
  const myCourses = data.courses.filter((c) => courseHasTeacher(c, teacher.id));
  const rows = myCourses.map((course) => {
    const dayIndex = DAYS.indexOf(course.day);
    const cells = weeks.map((w) => {
      if (dayIndex < 0) return { date: null, status: "none", amount: 0, holidayLabel: null };
      const date = new Date(w.weekStart);
      date.setDate(date.getDate() + dayIndex);
      if (date.getMonth() !== month || date.getFullYear() !== year) {
        return { date: null, status: "none", amount: 0, holidayLabel: null };
      }
      const dateStr = ymd(date);
      const rate = rateForCourse(teacher, course);
      const makeupKey = `${course.id}|${dateStr}`;
      const isMakeup = !!data.payrollMakeups?.[makeupKey];
      const holidayLabel = schoolHolidayLabel(data.schoolHolidays, dateStr) || publicHolidayLabel(dateStr);

      const absent = data.teacherAbsences.some((a) => a.teacherId === teacher.id && a.courseId === course.id && a.date === dateStr);
      if (absent) return { date: dateStr, status: "absence", amount: 0, holidayLabel: null };

      if (holidayLabel && !isMakeup) return { date: dateStr, status: "holiday", amount: 0, holidayLabel };
      if (holidayLabel && isMakeup) return { date: dateStr, status: "makeup", amount: rate, holidayLabel };

      const exclKey = `${course.id}|${dateStr}`;
      const manualAbsentKey = `${course.id}|${dateStr}`;
      const manuallyAbsent = !!data.payrollManualAbsences?.[manualAbsentKey];
      if (manuallyAbsent) return { date: dateStr, status: "absence_manuelle", amount: 0, holidayLabel: null };

      const manuallyExcluded = !!data.payrollExclusions[exclKey];
      if (manuallyExcluded) return { date: dateStr, status: "excluded", amount: 0, holidayLabel: null };

      return { date: dateStr, status: "worked", amount: rate, holidayLabel: null };
    });
    const total = cells.reduce((sum, c) => sum + c.amount, 0);
    return { course, cells, total };
  });
  const weekTotals = weeks.map((_, wi) => rows.reduce((sum, r) => sum + r.cells[wi].amount, 0));
  const grandTotal = rows.reduce((sum, r) => sum + r.total, 0);
  return { weeks, rows, weekTotals, grandTotal };
}

