function TeacherAbsencesAdmin({ data, setData }) {
  const list = data.teacherAbsences
    .slice()
    .sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));

  const markSeen = (id) => {
    setData({
      ...data,
      teacherAbsences: data.teacherAbsences.map((a) => (a.id === id ? { ...a, seen: true } : a)),
    });
  };

  const remove = (id) => {
    if (!window.confirm("Supprimer cette entrée de l'historique des absences ?")) return;
    setData({ ...data, teacherAbsences: data.teacherAbsences.filter((a) => a.id !== id) });
  };

  const unseenCount = data.teacherAbsences.filter((a) => !a.seen).length;

  return (
    <div className="space-y-5">
      {unseenCount > 0 && (
        <div className="flex items-center gap-2 rounded-lg border border-[#FF6B6B]/30 bg-[#FF6B6B]/10 px-4 py-3 text-sm text-[#FF6B6B]">
          <Bell size={16} />
          {unseenCount} absence{unseenCount > 1 ? "s" : ""} non consultée{unseenCount > 1 ? "s" : ""}
        </div>
      )}

      <div className="space-y-2">
        {list.map((a) => {
          const c = data.courses.find((c) => c.id === a.courseId);
          const t = data.teachers.find((t) => t.id === a.teacherId);
          return (
            <Card key={a.id} className={!a.seen ? "border-[#FFC857]/40" : ""}>
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div>
                  <div className="flex flex-wrap items-center gap-2 font-medium">
                    {t ? t.name : "Professeur supprimé"}
                    {!a.seen && (
                      <span className="inline-flex items-center gap-1.5 rounded-full border border-[#FFC857]/40 bg-[#FFC857]/15 px-2 py-0.5 text-[11px] text-[#FFC857]">
                        <span className="h-1.5 w-1.5 rounded-full bg-[#FFC857]" />
                        Nouveau
                      </span>
                    )}
                  </div>
                  <div className="mt-1 text-sm text-[#A79FC0]">
                    {c ? c.name : "Cours supprimé"} —{" "}
                    {new Date(a.date).toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long", year: "numeric" })}
                  </div>
                  {c && (
                    <div className="mt-1.5 flex flex-wrap items-center gap-2">
                      <VenueTag course={c} />
                    </div>
                  )}
                  {a.reason && <div className="mt-1.5 text-sm">{a.reason}</div>}
                  <div className="mt-1.5 text-xs text-[#5D5670]">
                    Signalé le {new Date(a.createdAt).toLocaleDateString("fr-FR")} à{" "}
                    {new Date(a.createdAt).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}
                  </div>
                </div>
                <div className="flex shrink-0 gap-1">
                  {!a.seen && (
                    <Button variant="ghost" className="!px-2.5 !py-1.5 text-xs" onClick={() => markSeen(a.id)}>
                      <Check size={14} /> Marquer comme vu
                    </Button>
                  )}
                  <button
                    onClick={async () => {
                      try {
                        await sendAbsenceEmail(a, t, c);
                      } catch (e) {
                        window.open(buildAbsenceMailto(a, t, c), "_blank");
                      }
                    }}
                    title="Renvoyer le brouillon d'email"
                    className="rounded p-1.5 text-[#5D5670] hover:bg-white/5 hover:text-[#A79FC0]"
                  >
                    <Mail size={15} />
                  </button>
                  <button onClick={() => remove(a.id)} className="rounded p-1.5 text-[#5D5670] hover:bg-[#FF6B6B]/10 hover:text-[#FF6B6B]">
                    <Trash2 size={15} />
                  </button>
                </div>
              </div>
            </Card>
          );
        })}
        {list.length === 0 && <p className="text-sm text-[#5D5670]">Aucune absence signalée par un professeur pour le moment.</p>}
      </div>
    </div>
  );
}

