const STATUS_INFO = {
  worked: { label: null, color: "#F5F1FA" },
  makeup: { label: null, color: "#FFC857" },
  absence: { label: "Absence signalée", color: "#FF6B6B" },
  absence_manuelle: { label: "Absent (non signalé)", color: "#FF6B6B" },
  excluded: { label: "Non compté", color: "#5D5670" },
  holiday: { label: "Vacances scolaires", color: "#60A5FA" },
  none: { label: "—", color: "#5D5670" },
};

function TeacherPayrollCard({ data, setData, teacher, year, month, readOnly }) {
  const [open, setOpen] = useState(false);
  const payroll = computeTeacherPayroll(data, teacher, year, month);
  const myCourses = data.courses.filter((c) => courseHasTeacher(c, teacher.id));

  if (myCourses.length === 0) return null;

  // Cycle à 3 états (hors vacances) : Payé → Non compté → Absent (non signalé) → Payé.
  // Réservé à l'admin/Dounya/Mike (readOnly=false pour ces comptes uniquement).
  const cycleWorkedStatus = (courseId, dateStr, currentStatus) => {
    if (readOnly || !dateStr) return;
    const key = `${courseId}|${dateStr}`;
    const nextExclusions = { ...data.payrollExclusions };
    const nextManualAbsences = { ...(data.payrollManualAbsences || {}) };
    delete nextExclusions[key];
    delete nextManualAbsences[key];
    if (currentStatus === "worked") {
      nextExclusions[key] = true;
    } else if (currentStatus === "excluded") {
      nextManualAbsences[key] = true;
    }
    // si "absence_manuelle" : les deux restent supprimées -> retour à "worked"
    setData({ ...data, payrollExclusions: nextExclusions, payrollManualAbsences: nextManualAbsences });
  };

  // Rattrapage pendant les vacances : toujours modifiable (admin, Dounya, et Mike),
  // puisque seuls ces comptes accèdent de toute façon à cet onglet.
  const toggleMakeup = (courseId, dateStr) => {
    if (!dateStr) return;
    const key = `${courseId}|${dateStr}`;
    const next = { ...(data.payrollMakeups || {}) };
    if (next[key]) delete next[key];
    else next[key] = true;
    setData({ ...data, payrollMakeups: next });
  };

  const cellClick = (courseId, cell) => {
    if (cell.status === "absence" || cell.status === "none") return;
    if (cell.status === "holiday" || cell.status === "makeup") {
      toggleMakeup(courseId, cell.date);
    } else {
      cycleWorkedStatus(courseId, cell.date, cell.status);
    }
  };

  const cellDisabled = (cell) =>
    cell.status === "absence" ||
    cell.status === "none" ||
    ((cell.status === "worked" || cell.status === "excluded" || cell.status === "absence_manuelle") && readOnly);

  const NEXT_LABEL = { worked: "non compté", excluded: "absent (non signalé)", absence_manuelle: "de nouveau payé" };

  const cellTitle = (cell) => {
    if (cell.status === "absence") return "Absence signalée par le professeur (non modifiable ici)";
    if (cell.status === "holiday") return `${cell.holidayLabel} — cliquer pour ajouter un cours de rattrapage`;
    if (cell.status === "makeup") return "Cours de rattrapage pendant les vacances — cliquer pour annuler";
    if (readOnly) return "";
    return `Cliquer pour marquer ${NEXT_LABEL[cell.status]}`;
  };

  return (
    <Card>
      <button onClick={() => setOpen((o) => !o)} className="flex w-full flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2.5">
          <span className="h-3 w-3 rounded-full" style={{ backgroundColor: teacher.color }} />
          <span className="font-medium">{teacher.name}</span>
          <span className="text-xs text-[#A79FC0]">{myCourses.length} cours</span>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-lg" style={{ fontFamily: "'Bebas Neue', sans-serif", color: "#FFC857" }}>
            {centsEuro(payroll.grandTotal)}
          </span>
          {open ? <ChevronUp size={16} className="text-[#A79FC0]" /> : <ChevronDown size={16} className="text-[#A79FC0]" />}
        </div>
      </button>

      {open && (
        <div className="mt-4 overflow-x-auto">
          <table className="w-full min-w-[560px] border-collapse text-sm">
            <thead>
              <tr className="border-b border-white/10 text-left text-[11px] uppercase tracking-[0.1em] text-[#5D5670]">
                <th className="pb-2 pr-3 font-normal">Cours</th>
                <th className="pb-2 pr-3 font-normal">Tarif</th>
                {payroll.weeks.map((w, i) => (
                  <th key={i} className="pb-2 px-2 text-right font-normal normal-case text-[#A79FC0]">
                    {w.weekStart.toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit" })}–
                    {w.weekEnd.toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit" })}
                  </th>
                ))}
                <th className="pb-2 pl-3 text-right font-normal">Total</th>
              </tr>
            </thead>
            <tbody>
              {payroll.rows.map(({ course, cells, total }) => (
                <tr key={course.id} className="border-b border-white/5 last:border-0">
                  <td className="py-2 pr-3">
                    <span className="inline-flex items-center gap-1.5">
                      <span className="h-2 w-2 shrink-0 rounded-full" style={{ backgroundColor: course.color }} />
                      {course.name}
                    </span>
                    <div className="text-xs text-[#5D5670]">{course.day}</div>
                  </td>
                  <td className="py-2 pr-3 text-[#A79FC0]">{centsEuro(rateForCourse(teacher, course))}</td>
                  {cells.map((cell, i) => (
                    <td key={i} className="py-2 px-2 text-right">
                      {cell.status === "none" ? (
                        <span className="text-[#5D5670]">—</span>
                      ) : (
                        <button
                          disabled={cellDisabled(cell)}
                          onClick={() => cellClick(course.id, cell)}
                          title={cellTitle(cell)}
                          className={`rounded px-1.5 py-0.5 ${!cellDisabled(cell) ? "hover:bg-white/5" : ""}`}
                          style={{ color: STATUS_INFO[cell.status].color }}
                        >
                          {cell.status === "worked" || cell.status === "makeup"
                            ? centsEuro(cell.amount)
                            : cell.status === "holiday"
                            ? cell.holidayLabel
                            : STATUS_INFO[cell.status].label}
                        </button>
                      )}
                    </td>
                  ))}
                  <td className="py-2 pl-3 text-right font-medium">{centsEuro(total)}</td>
                </tr>
              ))}
              <tr>
                <td className="pt-2 pr-3 text-xs uppercase tracking-[0.1em] text-[#5D5670]" colSpan={2}>
                  Total semaine
                </td>
                {payroll.weekTotals.map((wt, i) => (
                  <td key={i} className="pt-2 px-2 text-right text-xs text-[#A79FC0]">
                    {centsEuro(wt)}
                  </td>
                ))}
                <td className="pt-2 pl-3 text-right text-sm" style={{ color: "#FFC857" }}>
                  {centsEuro(payroll.grandTotal)}
                </td>
              </tr>
            </tbody>
          </table>
          <p className="mt-3 text-xs text-[#5D5670]">
            Les <span style={{ color: "#60A5FA" }}>vacances scolaires (Zone C)</span> et les{" "}
            <span style={{ color: "#60A5FA" }}>jours fériés</span> sont automatiquement exclus du calcul. Cliquez sur une case
            correspondante pour y ajouter un <span style={{ color: "#FFC857" }}>cours de rattrapage</span> (cliquez à nouveau pour
            l'annuler). Les <span style={{ color: "#FF6B6B" }}>absences signalées</span> par le professeur sont automatiquement
            exclues et non modifiables ici.
            {!readOnly &&
              " Cliquez sur un montant pour le faire passer par Payé → Non compté → Absent (non signalé) → Payé, selon la situation."}
          </p>
        </div>
      )}
    </Card>
  );
}

function PayrollView({ data, setData, readOnly }) {
  const PAYROLL_START = { year: 2026, month: 8 }; // Septembre 2026 (mois 0-indexé)
  const [year, setYear] = useState(PAYROLL_START.year);
  const [month, setMonth] = useState(PAYROLL_START.month);

  const isAtStart = year === PAYROLL_START.year && month === PAYROLL_START.month;

  const changeMonth = (delta) => {
    let m = month + delta;
    let y = year;
    if (m < 0) {
      m = 11;
      y--;
    } else if (m > 11) {
      m = 0;
      y++;
    }
    if (y < PAYROLL_START.year || (y === PAYROLL_START.year && m < PAYROLL_START.month)) return;
    setMonth(m);
    setYear(y);
  };

  const teachersWithCourses = sortTeachers(data.teachers.filter((t) => data.courses.some((c) => courseHasTeacher(c, t.id))));
  const monthGrandTotal = teachersWithCourses.reduce((sum, t) => sum + computeTeacherPayroll(data, t, year, month).grandTotal, 0);

  return (
    <div className="space-y-5">
      <TariffsPanel data={data} setData={setData} readOnly={readOnly} />
      <SchoolHolidaysPanel data={data} setData={setData} readOnly={readOnly} />

      <Card className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <button
            onClick={() => changeMonth(-1)}
            disabled={isAtStart}
            title={isAtStart ? "L'application démarre en septembre 2026" : ""}
            className="rounded-md border border-white/10 p-1.5 text-[#A79FC0] hover:bg-white/5 disabled:cursor-not-allowed disabled:opacity-30 disabled:hover:bg-transparent"
          >
            <ChevronLeft size={18} />
          </button>
          <span className="w-40 text-center text-lg" style={{ fontFamily: "'Bebas Neue', sans-serif", letterSpacing: "0.03em" }}>
            {MOIS_FR[month]} {year}
          </span>
          <button onClick={() => changeMonth(1)} className="rounded-md border border-white/10 p-1.5 text-[#A79FC0] hover:bg-white/5">
            <ChevronRight size={18} />
          </button>
        </div>
        <div className="flex items-center gap-2">
          <Wallet size={16} className="text-[#FFC857]" />
          <span className="text-xs uppercase tracking-[0.1em] text-[#A79FC0]">Total du mois</span>
          <span className="text-xl" style={{ fontFamily: "'Bebas Neue', sans-serif", color: "#FFC857" }}>
            {centsEuro(monthGrandTotal)}
          </span>
        </div>
      </Card>

      <div className="space-y-3">
        {teachersWithCourses.map((t) => (
          <TeacherPayrollCard key={t.id} data={data} setData={setData} teacher={t} year={year} month={month} readOnly={readOnly} />
        ))}
        {teachersWithCourses.length === 0 && <p className="text-sm text-[#5D5670]">Aucun professeur avec un cours assigné.</p>}
      </div>
    </div>
  );
}

/* -------------------------------- STATISTIQUES ------------------------------ */

function StatBar({ label, value, max, color, displayValue, sub }) {
  const pct = max ? Math.min(100, Math.round((value / max) * 100)) : 0;
  return (
    <div className="mb-3 last:mb-0">
      <div className="mb-1 flex items-center justify-between gap-2 text-sm">
        <span className="truncate">{label}</span>
        <span className="shrink-0 text-[#A79FC0]">{displayValue !== undefined ? displayValue : value}</span>
      </div>
      <div className="h-2 overflow-hidden rounded-full bg-white/5">
        <div className="h-2 rounded-full transition-all" style={{ width: `${pct}%`, backgroundColor: color }} />
      </div>
      {sub && <div className="mt-0.5 text-xs text-[#5D5670]">{sub}</div>}
    </div>
  );
}

function courseAttendanceStats(data, courseId) {
  let present = 0;
  let total = 0;
  Object.entries(data.attendance).forEach(([key, rec]) => {
    if (!key.startsWith(courseId + "|")) return;
    Object.values(rec.marks || {}).forEach((status) => {
      total++;
      if (status === "present") present++;
    });
  });
  return { present, total, rate: total ? Math.round((present / total) * 100) : null };
}

function StatisticsView({ data }) {
  const [siteFilter, setSiteFilter] = useState("all");

  const courses = siteFilter === "all" ? data.courses : data.courses.filter((c) => c.site === siteFilter);
  const courseIdsInScope = new Set(courses.map((c) => c.id));
  const studentsInScope =
    siteFilter === "all" ? data.students : data.students.filter((s) => (s.courseIds || []).some((cid) => courseIdsInScope.has(cid)));

  // KPIs globaux
  const totalStudents = studentsInScope.length;
  const totalCourses = courses.length;
  const teacherIdsInScope = new Set(courses.flatMap((c) => courseTeacherIds(c)));
  const totalTeachers = teacherIdsInScope.size;

  let presentCount = 0;
  let totalMarks = 0;
  Object.entries(data.attendance).forEach(([key, rec]) => {
    const courseId = key.split("|")[0];
    if (!courseIdsInScope.has(courseId)) return;
    Object.values(rec.marks || {}).forEach((s) => {
      totalMarks++;
      if (s === "present") presentCount++;
    });
  });
  const globalRate = totalMarks ? Math.round((presentCount / totalMarks) * 100) : null;

  // Répartition par statut dossier
  const statutCounts = Object.fromEntries(STATUTS.map((st) => [st.key, 0]));
  studentsInScope.forEach((s) => {
    if (statutCounts[s.statut] !== undefined) statutCounts[s.statut]++;
  });

  // Répartition par site (toujours tous sites, indépendant du filtre, pour comparaison)
  const siteStats = SITES.map((site) => {
    const siteCourses = data.courses.filter((c) => c.site === site);
    const siteCourseIds = new Set(siteCourses.map((c) => c.id));
    const siteStudents = data.students.filter((s) => (s.courseIds || []).some((cid) => siteCourseIds.has(cid)));
    const siteTeachers = new Set(siteCourses.flatMap((c) => courseTeacherIds(c)));
    return { site, courseCount: siteCourses.length, studentCount: siteStudents.length, teacherCount: siteTeachers.size };
  });
  const maxSiteStudents = Math.max(1, ...siteStats.map((s) => s.studentCount));

  // Répartition par jour de la semaine
  const dayStats = DAYS.filter((d) => d !== "Dimanche").map((day) => ({
    day,
    count: courses.filter((c) => c.day === day).length,
  }));
  const maxDayCount = Math.max(1, ...dayStats.map((d) => d.count));

  // Remplissage des cours
  const enrollment = courses
    .map((c) => ({ course: c, count: data.students.filter((s) => (s.courseIds || []).includes(c.id)).length }))
    .sort((a, b) => b.count - a.count);
  const maxEnrollment = Math.max(1, ...enrollment.map((e) => e.count));
  const topFilled = enrollment.slice(0, 5);
  const leastFilled = enrollment.slice().sort((a, b) => a.count - b.count).slice(0, 5);
  const avgEnrollment = courses.length ? (enrollment.reduce((sum, e) => sum + e.count, 0) / courses.length).toFixed(1) : "0";

  // Taux de présence par cours (avec un minimum de données pour être significatif)
  const attendanceByCourse = courses
    .map((c) => ({ course: c, ...courseAttendanceStats(data, c.id) }))
    .filter((c) => c.total >= 5);
  const bestAttendance = attendanceByCourse.slice().sort((a, b) => b.rate - a.rate).slice(0, 5);
  const worstAttendance = attendanceByCourse.slice().sort((a, b) => a.rate - b.rate).slice(0, 5);

  // Élèves par nombre de cours suivis
  const courseCountBuckets = [
    { label: "Aucun cours", test: (n) => n === 0 },
    { label: "1 cours", test: (n) => n === 1 },
    { label: "2 cours", test: (n) => n === 2 },
    { label: "3 cours", test: (n) => n === 3 },
    { label: "4 cours ou +", test: (n) => n >= 4 },
  ].map((b) => ({
    ...b,
    count: studentsInScope.filter((s) => b.test((s.courseIds || []).length)).length,
  }));

  // Absences profs
  const absencesInScope = data.teacherAbsences.filter((a) => courseIdsInScope.has(a.courseId));
  const absencesByTeacher = {};
  absencesInScope.forEach((a) => {
    absencesByTeacher[a.teacherId] = (absencesByTeacher[a.teacherId] || 0) + 1;
  });
  const topAbsences = Object.entries(absencesByTeacher)
    .map(([teacherId, count]) => ({ teacher: data.teachers.find((t) => t.id === teacherId), count }))
    .filter((a) => a.teacher)
    .sort((a, b) => b.count - a.count)
    .slice(0, 5);

  // Masse salariale du mois en cours (bornée au démarrage de l'onglet Salaires)
  const PAYROLL_START = { year: 2026, month: 8 };
  const now = new Date();
  let py = now.getFullYear();
  let pm = now.getMonth();
  if (py < PAYROLL_START.year || (py === PAYROLL_START.year && pm < PAYROLL_START.month)) {
    py = PAYROLL_START.year;
    pm = PAYROLL_START.month;
  }
  const teachersForPayroll = data.teachers.filter((t) => data.courses.some((c) => courseHasTeacher(c, t.id)));
  const monthPayrollTotal = teachersForPayroll.reduce((sum, t) => sum + computeTeacherPayroll(data, t, py, pm).grandTotal, 0);

  return (
    <div className="space-y-6">
      <SiteTabs value={siteFilter} onChange={setSiteFilter} />

      <div className="grid grid-cols-2 gap-4 md:grid-cols-5">
        <StatCard label="Élèves" value={totalStudents} accent="#FFC857" />
        <StatCard label="Cours" value={totalCourses} accent="#FF3E7F" />
        <StatCard label="Professeurs" value={totalTeachers} accent="#7C9EFF" />
        <StatCard label="Remplissage moyen" value={avgEnrollment} accent="#4ADE80" />
        <StatCard label="Taux de présence" value={globalRate === null ? "—" : `${globalRate}%`} accent="#60A5FA" />
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <h3 className="mb-4 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Statut dossier des élèves</h3>
          {STATUTS.map((st) => (
            <StatBar
              key={st.key}
              label={st.label}
              value={statutCounts[st.key]}
              max={totalStudents || 1}
              color={st.color}
              displayValue={`${statutCounts[st.key]} (${totalStudents ? Math.round((statutCounts[st.key] / totalStudents) * 100) : 0}%)`}
            />
          ))}
          {totalStudents === 0 && <p className="text-sm text-[#5D5670]">Aucun élève pour ce filtre.</p>}
        </Card>

        <Card>
          <h3 className="mb-4 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Élèves par nombre de cours suivis</h3>
          {courseCountBuckets.map((b) => (
            <StatBar key={b.label} label={b.label} value={b.count} max={totalStudents || 1} color="#FFC857" />
          ))}
        </Card>
      </div>

      <Card>
        <h3 className="mb-4 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Répartition par site</h3>
        <div className="grid gap-4 sm:grid-cols-3">
          {siteStats.map((s) => (
            <div key={s.site}>
              <div className="mb-1 text-sm font-medium" style={{ color: SITE_ACCENTS[s.site] }}>
                {s.site.replaceAll("-", " ")}
              </div>
              <div className="mb-2 text-xs text-[#5D5670]">
                {s.courseCount} cours · {s.teacherCount} prof(s)
              </div>
              <StatBar label="Élèves" value={s.studentCount} max={maxSiteStudents} color={SITE_ACCENTS[s.site]} />
            </div>
          ))}
        </div>
      </Card>

      <Card>
        <h3 className="mb-4 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Cours par jour de la semaine</h3>
        <div className="grid gap-x-6 gap-y-3 sm:grid-cols-2">
          {dayStats.map((d) => (
            <StatBar key={d.day} label={d.day} value={d.count} max={maxDayCount} color="#FF7A45" />
          ))}
        </div>
      </Card>

      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <h3 className="mb-4 flex items-center gap-2 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">
            <TrendingUp size={15} className="text-[#4ADE80]" /> Cours les plus remplis
          </h3>
          {topFilled.map(({ course, count }) => (
            <StatBar
              key={course.id}
              label={`${course.name} (${course.day})`}
              value={count}
              max={maxEnrollment}
              color={course.color}
              displayValue={`${count} élève(s)`}
            />
          ))}
          {topFilled.length === 0 && <p className="text-sm text-[#5D5670]">Aucun cours pour ce filtre.</p>}
        </Card>

        <Card>
          <h3 className="mb-4 flex items-center gap-2 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">
            <TrendingDown size={15} className="text-[#FF6B6B]" /> Cours les moins remplis
          </h3>
          {leastFilled.map(({ course, count }) => (
            <StatBar
              key={course.id}
              label={`${course.name} (${course.day})`}
              value={count}
              max={maxEnrollment}
              color={course.color}
              displayValue={`${count} élève(s)`}
            />
          ))}
          {leastFilled.length === 0 && <p className="text-sm text-[#5D5670]">Aucun cours pour ce filtre.</p>}
        </Card>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <h3 className="mb-4 flex items-center gap-2 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">
            <TrendingUp size={15} className="text-[#4ADE80]" /> Meilleurs taux de présence
          </h3>
          {bestAttendance.map(({ course, rate, total }) => (
            <StatBar
              key={course.id}
              label={`${course.name} (${course.day})`}
              value={rate}
              max={100}
              color="#4ADE80"
              displayValue={`${rate}%`}
              sub={`sur ${total} présence(s) enregistrée(s)`}
            />
          ))}
          {bestAttendance.length === 0 && (
            <p className="text-sm text-[#5D5670]">Pas encore assez d'appels enregistrés pour ce filtre.</p>
          )}
        </Card>

        <Card>
          <h3 className="mb-4 flex items-center gap-2 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">
            <TrendingDown size={15} className="text-[#FF6B6B]" /> Taux de présence à surveiller
          </h3>
          {worstAttendance.map(({ course, rate, total }) => (
            <StatBar
              key={course.id}
              label={`${course.name} (${course.day})`}
              value={rate}
              max={100}
              color="#FF6B6B"
              displayValue={`${rate}%`}
              sub={`sur ${total} présence(s) enregistrée(s)`}
            />
          ))}
          {worstAttendance.length === 0 && (
            <p className="text-sm text-[#5D5670]">Pas encore assez d'appels enregistrés pour ce filtre.</p>
          )}
        </Card>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <h3 className="mb-4 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Absences profs les plus fréquentes</h3>
          {topAbsences.map(({ teacher, count }) => (
            <StatBar
              key={teacher.id}
              label={teacher.name}
              value={count}
              max={Math.max(1, ...topAbsences.map((a) => a.count))}
              color="#FF6B6B"
              displayValue={`${count} absence(s)`}
            />
          ))}
          {topAbsences.length === 0 && <p className="text-sm text-[#5D5670]">Aucune absence signalée pour ce filtre.</p>}
        </Card>

        <Card className="flex flex-col justify-between">
          <div>
            <h3 className="mb-2 flex items-center gap-2 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">
              <Wallet size={15} className="text-[#FFC857]" /> Masse salariale (mois en cours)
            </h3>
            <p className="text-xs text-[#5D5670]">
              {MOIS_FR[pm]} {py} — tous sites confondus, vacances et jours fériés déjà exclus.
            </p>
          </div>
          <span className="mt-4 text-3xl" style={{ fontFamily: "'Bebas Neue', sans-serif", color: "#FFC857" }}>
            {centsEuro(monthPayrollTotal)}
          </span>
        </Card>
      </div>
    </div>
  );
}

/* ---------------------------- Présences (partagé) -------------------------- */

function AttendanceHistory({ data, scopeTeacherId }) {
  const courses = scopeTeacherId ? data.courses.filter((c) => courseHasTeacher(c, scopeTeacherId)) : data.courses;
  const [courseId, setCourseId] = useState(courses[0]?.id || "");

  useEffect(() => {
    if (!courses.find((c) => c.id === courseId)) setCourseId(courses[0]?.id || "");
  }, [courses.length]);

  const course = courses.find((c) => c.id === courseId);
  const sessionKeys = Object.keys(data.attendance)
    .filter((k) => (course ? k.startsWith(course.id + "|") : false))
    .sort()
    .reverse();
  const grouped = groupBySite(courses);

  return (
    <div className="space-y-5">
      <Field label="Cours">
        <select className={inputCls + " max-w-sm"} value={courseId} onChange={(e) => setCourseId(e.target.value)}>
          {grouped.map((g) => (
            <optgroup key={g.site} label={g.site.replaceAll("-", " ")}>
              {g.courses.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.name} — {c.day} {c.time}
                </option>
              ))}
            </optgroup>
          ))}
        </select>
      </Field>

      {course && (
        <div className="flex flex-wrap items-center gap-2 text-xs text-[#A79FC0]">
          <VenueTag course={course} />
          <span>{course.site.replaceAll("-", " ")}</span>
        </div>
      )}

      {courses.length === 0 && <p className="text-sm text-[#5D5670]">Aucun cours disponible.</p>}

      {course && sessionKeys.length === 0 && (
        <p className="text-sm text-[#5D5670]">Aucun appel enregistré pour ce cours pour le moment.</p>
      )}

      <div className="space-y-4">
        {sessionKeys.map((key) => {
          const date = key.split("|")[1];
          const rec = data.attendance[key];
          const marks = rec.marks || {};
          const students = sortStudents(
            Object.keys(marks)
              .map((sid) => data.students.find((s) => s.id === sid))
              .filter(Boolean)
          );
          const roleLabel = { admin: "administrateur", staff: "staff", teacher: "professeur" }[rec.recordedBy?.type] || "";
          return (
            <Card key={key}>
              <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
                <span className="font-medium">
                  {new Date(date).toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long", year: "numeric" })}
                </span>
                <span className="text-xs text-[#A79FC0]">{students.length} élève(s)</span>
              </div>
              <div className="mb-3 text-xs text-[#5D5670]">
                {rec.recordedBy ? (
                  <>
                    Appel fait par <span className="text-[#A79FC0]">{rec.recordedBy.name}</span>
                    {roleLabel && ` (${roleLabel})`}
                  </>
                ) : (
                  "Appel importé (auteur inconnu)"
                )}
              </div>
              <div className="flex flex-wrap gap-2">
                {students.map((s) => (
                  <div key={s.id} className="flex items-center gap-2 rounded-md border border-white/10 bg-[#100D18] px-3 py-1.5 text-sm">
                    <span>
                      {s.prenom} {s.nom}
                    </span>
                    <DossierBadge statut={s.statut} />
                    <StatusPill status={marks[s.id]} />
                  </div>
                ))}
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

/* -------------------------------- TEACHER --------------------------------- */

function MyAccountPanel({ data, setData, kind, id }) {
  const list = kind === "teacher" ? data.teachers : data.staff;
  const account = list.find((a) => a.id === id);
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [saved, setSaved] = useState(false);

  const save = () => {
    if (!password.trim() || password.length < 4) {
      window.alert("Le mot de passe doit contenir au moins 4 caractères.");
      return;
    }
    if (password !== confirm) {
      window.alert("Les deux mots de passe ne correspondent pas.");
      return;
    }
    const field = kind === "teacher" ? "teachers" : "staff";
    setData({
      ...data,
      [field]: list.map((a) => (a.id === id ? { ...a, password } : a)),
    });
    setPassword("");
    setConfirm("");
    setSaved(true);
    setTimeout(() => setSaved(false), 2500);
  };

  if (!account) return null;

  return (
    <Card className="max-w-md">
      <h3 className="mb-4 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Mon compte</h3>
      <div className="mb-4 space-y-1 text-sm">
        <div>
          <span className="text-[#5D5670]">Nom : </span>
          {account.name}
        </div>
        <div>
          <span className="text-[#5D5670]">Identifiant : </span>@{account.username}
        </div>
      </div>
      <Barre className="mb-4" />
      <h4 className="mb-3 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Changer mon mot de passe</h4>
      <div className="space-y-4">
        <Field label="Nouveau mot de passe">
          <input className={inputCls} type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        </Field>
        <Field label="Confirmer le nouveau mot de passe">
          <input className={inputCls} type="password" value={confirm} onChange={(e) => setConfirm(e.target.value)} />
        </Field>
        <button
          type="button"
          onClick={save}
          style={{
            padding: "10px 20px",
            borderRadius: "8px",
            background: "linear-gradient(135deg, #FFC857, #FFD976)",
            color: "#100D18",
            fontSize: "14px",
            fontWeight: 700,
            border: "none",
            cursor: "pointer",
            display: "inline-flex",
            alignItems: "center",
            gap: "8px",
            boxShadow: "0 4px 16px -4px rgba(255,200,87,0.6)",
          }}
        >
          <Check size={16} /> Enregistrer
        </button>
        {saved && <p className="text-sm text-[#4ADE80]">Mot de passe mis à jour ✓</p>}
      </div>
    </Card>
  );
}

function TeacherApp({ data, setData, teacherId, onLogout }) {
  const [page, setPage] = useState("roll");
  const teacher = data.teachers.find((t) => t.id === teacherId);

  const nav = [
    { key: "roll", label: "Faire l'appel", icon: <CalendarDays size={16} /> },
    { key: "history", label: "Historique", icon: <Users size={16} /> },
    { key: "absence", label: "Signaler une absence", icon: <CalendarX size={16} /> },
    { key: "account", label: "Mon compte", icon: <UserCog size={16} /> },
  ];
  const titles = {
    roll: ["Faire l'appel", `Bonjour ${teacher ? teacher.name.split(" ")[0] : ""}`],
    history: ["Historique", "Vos appels précédents"],
    absence: ["Signaler une absence", "Prévenez l'administration pour un cours que vous ne pourrez pas assurer"],
    account: ["Mon compte", "Vos informations et votre mot de passe"],
  };

  return (
    <Shell title={titles[page][0]} subtitle={titles[page][1]} nav={nav} active={page} onNav={setPage} onLogout={onLogout}>
      {page === "roll" && (
        <TakeRoll
          data={data}
          setData={setData}
          courses={data.courses.filter((c) => courseHasTeacher(c, teacherId))}
          emptyMessage="Aucun cours ne vous est assigné pour le moment. Contactez l'administration."
          actor={{ type: "teacher", id: teacherId, name: teacher ? teacher.name : "Professeur" }}
        />
      )}
      {page === "history" && <AttendanceHistory data={data} scopeTeacherId={teacherId} />}
      {page === "absence" && <ReportAbsence data={data} setData={setData} teacherId={teacherId} />}
      {page === "account" && <MyAccountPanel data={data} setData={setData} kind="teacher" id={teacherId} />}
    </Shell>
  );
}

function StaffApp({ data, setData, staffId, onLogout }) {
  const [page, setPage] = useState("roll");
  const staffMember = data.staff.find((s) => s.id === staffId);
  const isMike = nameMatches(staffMember?.name, "Mike");

  const nav = [
    { key: "roll", label: "Faire l'appel", icon: <CalendarDays size={16} /> },
    { key: "planning", label: "Planning", icon: <LayoutDashboard size={16} /> },
    { key: "students", label: "Élèves", icon: <Users size={16} /> },
    ...(isMike
      ? [
          { key: "statistics", label: "Statistiques", icon: <BarChart3 size={16} /> },
          { key: "teachers", label: "Professeurs", icon: <GraduationCap size={16} /> },
          { key: "payroll", label: "Salaires", icon: <Wallet size={16} /> },
          {
            key: "teacherAbsences",
            label: "Absences profs",
            icon: <CalendarX size={16} />,
            badge: data.teacherAbsences.filter((a) => !a.seen).length || null,
          },
          { key: "attendance", label: "Présences", icon: <ClipboardCheck size={16} /> },
        ]
      : []),
    { key: "account", label: "Mon compte", icon: <UserCog size={16} /> },
  ];
  const titles = {
    roll: ["Faire l'appel", `Bonjour ${staffMember ? staffMember.name.split(" ")[0] : ""}`],
    planning: ["Planning", "Vue d'ensemble des 3 sites (lecture seule)"],
    students: ["Élèves", "Annuaire des élèves et de leurs cours (lecture seule)"],
    statistics: ["Statistiques", "Vue d'analyse : remplissage, présence, statuts, absences, masse salariale"],
    teachers: ["Professeurs", "Gérer les comptes des professeurs"],
    payroll: ["Salaires", "Lecture mensuelle par professeur, détail par semaine"],
    teacherAbsences: ["Absences profs", "Absences signalées par les professeurs"],
    attendance: ["Présences", "Historique de tous les cours"],
    account: ["Mon compte", "Vos informations et votre mot de passe"],
  };

  return (
    <Shell title={titles[page][0]} subtitle={titles[page][1]} nav={nav} active={page} onNav={setPage} onLogout={onLogout}>
      {page === "roll" && (
        <TakeRoll
          data={data}
          setData={setData}
          courses={data.courses}
          emptyMessage="Aucun cours n'a encore été créé."
          actor={{ type: "staff", id: staffId, name: staffMember ? staffMember.name : "Staff" }}
          showTeacherFilter
        />
      )}
      {page === "planning" && <Dashboard data={data} showSynthese={isMike} />}
      {page === "students" && <ManageStudents data={data} setData={setData} readOnly />}
      {page === "statistics" && isMike && <StatisticsView data={data} />}
      {page === "teachers" && isMike && <ManageTeachers data={data} setData={setData} />}
      {page === "payroll" && isMike && <PayrollView data={data} setData={setData} />}
      {page === "teacherAbsences" && isMike && <TeacherAbsencesAdmin data={data} setData={setData} />}
      {page === "attendance" && isMike && <AttendanceHistory data={data} scopeTeacherId={null} />}
      {page === "account" && <MyAccountPanel data={data} setData={setData} kind="staff" id={staffId} />}
    </Shell>
  );
}

function ReportAbsence({ data, setData, teacherId }) {
  const myCourses = data.courses.filter((c) => courseHasTeacher(c, teacherId));
  const [form, setForm] = useState({ courseId: myCourses[0]?.id || "", date: todayISO(), reason: "" });
  const [emailStatus, setEmailStatus] = useState(null); // { type: "sending"|"sent"|"fallback", error? }

  const submit = async () => {
    if (!form.courseId || !form.date) {
      window.alert("Merci de choisir un cours et une date.");
      return;
    }
    const entry = {
      id: uid(),
      teacherId,
      courseId: form.courseId,
      date: form.date,
      reason: form.reason.trim(),
      createdAt: new Date().toISOString(),
      seen: false,
    };
    setData({ ...data, teacherAbsences: [entry, ...data.teacherAbsences] });
    const course = myCourses.find((c) => c.id === form.courseId);
    const teacher = data.teachers.find((t) => t.id === teacherId);
    setForm({ courseId: myCourses[0]?.id || "", date: todayISO(), reason: "" });
    setEmailStatus({ type: "sending" });
    try {
      await sendAbsenceEmail(entry, teacher, course);
      setEmailStatus({ type: "sent" });
      setTimeout(() => setEmailStatus(null), 6000);
    } catch (e) {
      console.error("Envoi automatique échoué :", e);
      window.open(buildAbsenceMailto(entry, teacher, course), "_blank");
      setEmailStatus({ type: "fallback", error: e && e.message ? e.message : String(e) });
    }
  };

  const myAbsences = data.teacherAbsences
    .filter((a) => a.teacherId === teacherId)
    .slice()
    .sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));

  if (myCourses.length === 0) {
    return <p className="text-sm text-[#5D5670]">Aucun cours ne vous est assigné pour le moment.</p>;
  }

  return (
    <div className="space-y-6">
      <Card className="max-w-lg border-[#FF3E7F]/30">
        <h3 className="mb-4 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Nouvelle absence</h3>
        <div className="space-y-4">
          <Field label="Cours" required>
            <select className={inputCls} value={form.courseId} onChange={(e) => setForm({ ...form, courseId: e.target.value })}>
              {courseOptionGroups(myCourses)}
            </select>
          </Field>
          <Field label="Date" required>
            <input className={inputCls} type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
          </Field>
          <Field label="Motif (optionnel)">
            <input
              className={inputCls}
              placeholder="Ex. Arrêt maladie, empêchement personnel…"
              value={form.reason}
              onChange={(e) => setForm({ ...form, reason: e.target.value })}
            />
          </Field>
          <button
            type="button"
            onClick={submit}
            style={{
              width: "100%",
              padding: "12px",
              borderRadius: "8px",
              background: "#FF3E7F",
              color: "#fff",
              fontSize: "14px",
              fontWeight: 700,
              border: "none",
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: "8px",
              boxShadow: "0 4px 16px -4px rgba(255,62,127,0.6)",
            }}
          >
            <CalendarX size={16} /> Signaler mon absence
          </button>
          {emailStatus?.type === "sending" && <p className="text-sm text-[#A79FC0]">Absence enregistrée · envoi de l'email en cours…</p>}
          {emailStatus?.type === "sent" && (
            <p className="text-sm text-[#4ADE80]">Absence signalée · email envoyé automatiquement à {ADMIN_EMAIL} ✓</p>
          )}
          {emailStatus?.type === "fallback" && (
            <div className="rounded-md border border-[#FFC857]/30 bg-[#FFC857]/10 p-3">
              <p className="text-sm text-[#FFC857]">
                Absence signalée · l'envoi automatique a échoué, un brouillon d'email vient de s'ouvrir à la place.
              </p>
              {emailStatus.error && <p className="mt-1 text-xs text-[#5D5670]">Détail technique : {emailStatus.error}</p>}
            </div>
          )}
          <p className="text-xs text-[#5D5670]">
            L'email part automatiquement vers <span className="text-[#A79FC0]">{ADMIN_EMAIL}</span>. La toute première fois, cette
            adresse recevra un email d'activation à confirmer d'un clic — ensuite, tout est envoyé sans aucune action de votre part.
          </p>
        </div>
      </Card>

      <div>
        <h3 className="mb-3 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Mes absences signalées</h3>
        <div className="space-y-2">
          {myAbsences.map((a) => {
            const c = data.courses.find((c) => c.id === a.courseId);
            const teacher = data.teachers.find((t) => t.id === teacherId);
            return (
              <Card key={a.id} className="flex flex-wrap items-center justify-between gap-3">
                <div>
                  <div className="font-medium">
                    {c ? c.name : "Cours supprimé"} — {new Date(a.date).toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long" })}
                  </div>
                  {a.reason && <div className="mt-1 text-xs text-[#A79FC0]">{a.reason}</div>}
                </div>
                <div className="flex items-center gap-2">
                  <span
                    className="rounded-full border px-2.5 py-0.5 text-xs"
                    style={
                      a.seen
                        ? { borderColor: "rgba(74,222,128,0.3)", color: "#4ADE80", backgroundColor: "rgba(74,222,128,0.1)" }
                        : { borderColor: "rgba(255,200,87,0.3)", color: "#FFC857", backgroundColor: "rgba(255,200,87,0.1)" }
                    }
                  >
                    {a.seen ? "Vu par l'administration" : "En attente"}
                  </span>
                  <button
                    onClick={async () => {
                      try {
                        await sendAbsenceEmail(a, teacher, c);
                      } catch (e) {
                        window.open(buildAbsenceMailto(a, teacher, c), "_blank");
                      }
                    }}
                    title="Renvoyer le brouillon d'email"
                    className="rounded p-1.5 text-[#5D5670] hover:bg-white/5 hover:text-[#A79FC0]"
                  >
                    <Mail size={15} />
                  </button>
                </div>
              </Card>
            );
          })}
          {myAbsences.length === 0 && <p className="text-sm text-[#5D5670]">Aucune absence signalée pour le moment.</p>}
        </div>
      </div>
    </div>
  );
}

function TakeRoll({ data, setData, courses, emptyMessage, actor, showTeacherFilter }) {
  const myCourses = courses;
  const [courseId, setCourseId] = useState("");
  const [teacherFilter, setTeacherFilter] = useState("");
  const [date, setDate] = useState(todayISO());

  useEffect(() => {
    if (courseId && !myCourses.find((c) => c.id === courseId)) setCourseId("");
  }, [myCourses.length]);

  useEffect(() => {
    setCourseId("");
  }, [teacherFilter]);

  const visibleCourses = showTeacherFilter && teacherFilter ? myCourses.filter((c) => courseHasTeacher(c, teacherFilter)) : myCourses;
  const filterableTeachers = sortTeachers(data.teachers.filter((t) => myCourses.some((c) => courseHasTeacher(c, t.id))));

  const course = myCourses.find((c) => c.id === courseId);
  const roster = course ? sortStudents(data.students.filter((s) => (s.courseIds || []).includes(course.id))) : [];
  const key = course ? `${course.id}|${date}` : null;
  const [marks, setMarks] = useState(key ? data.attendance[key]?.marks || {} : {});
  const [savedFlash, setSavedFlash] = useState(false);
  const [teacherNotes, setTeacherNotes] = useState({});
  const [showTrialForm, setShowTrialForm] = useState(false);
  const [trialForm, setTrialForm] = useState({ nom: "", prenom: "", telephone: "", email: "" });
  const grouped = groupBySite(visibleCourses);
  const existingRecord = key ? data.attendance[key] : null;

  useEffect(() => {
    setMarks(data.attendance[key]?.marks || {});
    setShowTrialForm(false);
  }, [key]);

  if (myCourses.length === 0) {
    return <p className="text-sm text-[#5D5670]">{emptyMessage || "Aucun cours disponible."}</p>;
  }

  const setMark = (studentId, status) => {
    setMarks((m) => ({ ...m, [studentId]: m[studentId] === status ? undefined : status }));
  };

  const save = () => {
    setData({
      ...data,
      attendance: {
        ...data.attendance,
        [key]: { marks, recordedBy: actor || null, recordedAt: new Date().toISOString() },
      },
    });
    setSavedFlash(true);
    setTimeout(() => setSavedFlash(false), 1800);
  };

  const markAll = (status) => {
    const next = {};
    roster.forEach((s) => (next[s.id] = status));
    setMarks(next);
  };

  const updateComment = (studentId, value) => {
    setData({ ...data, students: data.students.map((s) => (s.id === studentId ? { ...s, commentaire: value } : s)) });
  };

  const appendComment = (studentId) => {
    const addition = (teacherNotes[studentId] || "").trim();
    if (!addition) return;
    const s = data.students.find((s) => s.id === studentId);
    const existing = (s?.commentaire || "").trim();
    updateComment(studentId, existing ? `${existing}\n${addition}` : addition);
    setTeacherNotes((n) => ({ ...n, [studentId]: "" }));
  };

  const addTrialStudent = () => {
    if (!trialForm.nom.trim() && !trialForm.prenom.trim()) {
      window.alert("Merci de renseigner au moins le nom ou le prénom.");
      return;
    }
    const newStudent = {
      id: uid(),
      nom: trialForm.nom.trim(),
      prenom: trialForm.prenom.trim(),
      telephone: trialForm.telephone.trim(),
      email: trialForm.email.trim(),
      statut: "en_cours",
      commentaire: "",
      courseIds: [course.id],
    };
    setData({ ...data, students: [...data.students, newStudent] });
    setMarks((m) => ({ ...m, [newStudent.id]: "present" }));
    setTrialForm({ nom: "", prenom: "", telephone: "", email: "" });
    setShowTrialForm(false);
  };

  const dur = course ? durationLabel(course.duration) : null;

  return (
    <div className="space-y-5">
      <div className={`grid gap-4 sm:max-w-2xl ${showTeacherFilter ? "sm:grid-cols-3" : "sm:grid-cols-2"}`}>
        {showTeacherFilter && (
          <Field label="Professeur">
            <select className={inputCls} value={teacherFilter} onChange={(e) => setTeacherFilter(e.target.value)}>
              <option value="">Tous les professeurs</option>
              {filterableTeachers.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                </option>
              ))}
            </select>
          </Field>
        )}
        <Field label="Cours">
          <select className={inputCls} value={courseId} onChange={(e) => setCourseId(e.target.value)}>
            <option value="" disabled>
              Choisissez un cours dans la liste
            </option>
            {grouped.map((g) => (
              <optgroup key={g.site} label={g.site.replaceAll("-", " ")}>
                {g.courses.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name} — {c.day} {c.time}
                  </option>
                ))}
              </optgroup>
            ))}
          </select>
        </Field>
        <Field label="Date">
          <input className={inputCls} type="date" value={date} onChange={(e) => setDate(e.target.value)} />
        </Field>
      </div>

      <Barre />

      {!course && <p className="text-sm text-[#5D5670]">Sélectionnez un cours ci-dessus pour faire l'appel.</p>}

      {course && (
        <>
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex flex-wrap items-center gap-2">
              <span className="h-3 w-3 rounded-full" style={{ backgroundColor: course.color }} />
              <span className="font-medium">{course.name}</span>
              <span className="text-sm text-[#A79FC0]">
                · {course.time}
                {dur ? ` (${dur})` : ""} · {roster.length} élève(s)
              </span>
              <VenueTag course={course} />
              <span className="text-sm text-[#A79FC0]">· {courseTeacherNames(course, data.teachers)}</span>
            </div>
          </div>
          {existingRecord?.recordedBy && (
            <p className="text-xs text-[#5D5670]">
              Appel déjà enregistré par <span className="text-[#A79FC0]">{existingRecord.recordedBy.name}</span>
              {existingRecord.recordedBy.type === "admin" && " (administrateur)"}
              {existingRecord.recordedBy.type === "staff" && " (staff)"}
              {existingRecord.recordedBy.type === "teacher" && " (professeur)"}
            </p>
          )}
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex flex-wrap items-center gap-2 text-xs">
              <button onClick={() => markAll("present")} className="rounded-full border border-[#4ADE80]/30 bg-[#4ADE80]/10 px-3 py-1 text-[#4ADE80]">
                Tout présent
              </button>
              <button onClick={() => setMarks({})} className="rounded-full border border-white/10 px-3 py-1 text-[#A79FC0]">
                Réinitialiser
              </button>
            </div>
            <button
              onClick={() => setShowTrialForm((v) => !v)}
              className="flex items-center gap-1.5 rounded-full border border-[#60A5FA]/40 bg-[#60A5FA]/10 px-3 py-1 text-xs text-[#60A5FA]"
            >
              <Plus size={13} /> Élève à l'essai
            </button>
          </div>

          {showTrialForm && (
            <Card className="border-[#60A5FA]/30">
              <h4 className="mb-3 text-sm uppercase tracking-[0.14em] text-[#A79FC0]">Ajouter un élève à l'essai</h4>
              <p className="mb-3 text-xs text-[#5D5670]">
                Il sera automatiquement inscrit à ce cours avec le statut{" "}
                <span className="text-[#60A5FA]">Cours d'essai</span>, et marqué présent aujourd'hui.
              </p>
              <div className="grid gap-3 sm:grid-cols-2">
                <input
                  className={inputCls}
                  placeholder="Nom"
                  value={trialForm.nom}
                  onChange={(e) => setTrialForm({ ...trialForm, nom: e.target.value })}
                />
                <input
                  className={inputCls}
                  placeholder="Prénom"
                  value={trialForm.prenom}
                  onChange={(e) => setTrialForm({ ...trialForm, prenom: e.target.value })}
                />
                <input
                  className={inputCls}
                  placeholder="Téléphone (optionnel)"
                  value={trialForm.telephone}
                  onChange={(e) => setTrialForm({ ...trialForm, telephone: e.target.value })}
                />
                <input
                  className={inputCls}
                  type="email"
                  placeholder="Adresse mail (optionnel)"
                  value={trialForm.email}
                  onChange={(e) => setTrialForm({ ...trialForm, email: e.target.value })}
                  onKeyDown={(e) => e.key === "Enter" && addTrialStudent()}
                />
              </div>
              <div className="mt-3 flex flex-wrap gap-3">
                <button
                  type="button"
                  onClick={addTrialStudent}
                  style={{
                    padding: "9px 18px",
                    borderRadius: "8px",
                    background: "#60A5FA",
                    color: "#100D18",
                    fontSize: "13px",
                    fontWeight: 700,
                    border: "none",
                    cursor: "pointer",
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "7px",
                  }}
                >
                  <Plus size={15} /> Ajouter à l'essai
                </button>
                <Button variant="ghost" className="!px-2.5 !py-1.5 text-xs" onClick={() => setShowTrialForm(false)}>
                  <X size={14} /> Annuler
                </Button>
              </div>
            </Card>
          )}

          <div className="space-y-2">
            {roster.map((s) => {
              const hasComment = s.commentaire && s.commentaire.trim();
              return (
                <div key={s.id} className="rounded-lg border border-white/10 bg-[#1C1829] px-4 py-3">
                  <div className="flex items-center justify-between gap-3">
                    <div className="flex flex-wrap items-center gap-2">
                      <span>
                        {s.prenom} {s.nom}
                      </span>
                      <DossierBadge statut={s.statut} />
                    </div>
                    <div className="flex gap-1.5">
                      {[
                        { v: "present", label: "Présent", cls: "border-[#4ADE80]/40 text-[#4ADE80]" },
                        { v: "late", label: "Retard", cls: "border-[#FFC857]/40 text-[#FFC857]" },
                        { v: "absent", label: "Absent", cls: "border-[#FF6B6B]/40 text-[#FF6B6B]" },
                      ].map((opt) => (
                        <button
                          key={opt.v}
                          onClick={() => setMark(s.id, opt.v)}
                          className={`rounded-md border px-2.5 py-1 text-xs transition ${opt.cls} ${
                            marks[s.id] === opt.v ? "bg-white/10" : "bg-transparent opacity-50 hover:opacity-100"
                          }`}
                        >
                          {opt.label}
                        </button>
                      ))}
                    </div>
                  </div>

                  {hasComment && (
                    <div className="mt-2.5 rounded-md border border-[#FFC857]/25 bg-[#FFC857]/5 p-2.5">
                      <div className="mb-1.5 flex items-center gap-1.5 text-[10px] uppercase tracking-[0.12em] text-[#FFC857]">
                        <MessageSquare size={11} /> Commentaire
                      </div>
                      {actor?.type === "teacher" ? (
                        <>
                          <p className="whitespace-pre-wrap text-sm text-[#F5F1FA]">{s.commentaire}</p>
                          <div className="mt-2 flex flex-wrap gap-1.5">
                            <input
                              className={inputCls + " !py-1.5 max-w-xs text-xs"}
                              placeholder="Ajouter une remarque (sans effacer)…"
                              value={teacherNotes[s.id] || ""}
                              onChange={(e) => setTeacherNotes((n) => ({ ...n, [s.id]: e.target.value }))}
                              onKeyDown={(e) => e.key === "Enter" && appendComment(s.id)}
                            />
                            <Button variant="ghost" className="!px-2.5 !py-1.5 text-xs" onClick={() => appendComment(s.id)}>
                              <Plus size={13} /> Ajouter
                            </Button>
                          </div>
                        </>
                      ) : (
                        <textarea
                          className={inputCls + " text-sm"}
                          rows={2}
                          value={s.commentaire}
                          onChange={(e) => updateComment(s.id, e.target.value)}
                        />
                      )}
                    </div>
                  )}
                </div>
              );
            })}
            {roster.length === 0 && <p className="text-sm text-[#5D5670]">Aucun élève inscrit à ce cours.</p>}
          </div>

          <div className="flex items-center gap-3 pt-2">
            <Button onClick={save} variant="gold">
              <Check size={16} /> Enregistrer l'appel
            </Button>
            {savedFlash && <span className="text-sm text-[#4ADE80]">Appel enregistré ✓</span>}
          </div>
        </>
      )}
    </div>
  );
}

/* --------------------------------- ROOT ----------------------------------- */

export default function App() {
  const [data, setDataRaw] = useState(null);
  const [session, setSession] = useState(null); // { role, teacherId? }
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadData().then((d) => {
      setDataRaw(d);
      setLoading(false);
    });
  }, []);

  const setData = useCallback((next) => {
    setDataRaw(next);
    saveData(next);
  }, []);

  if (loading || !data) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#100D18] text-[#A79FC0]">
        <div className="flex items-center gap-2 text-sm">
          <div className="h-4 w-4 animate-spin rounded-full border-2 border-[#FF3E7F] border-t-transparent" />
          Chargement du studio…
        </div>
      </div>
    );
  }

  return (
    <div>
      {!session && <LoginScreen data={data} onLogin={setSession} />}
      {session?.role === "admin" && <AdminApp data={data} setData={setData} onLogout={() => setSession(null)} />}
      {session?.role === "teacher" && (
        <TeacherApp data={data} setData={setData} teacherId={session.teacherId} onLogout={() => setSession(null)} />
      )}
      {session?.role === "staff" &&
        (() => {
          const staffMember = data.staff.find((s) => s.id === session.staffId);
          if (nameMatches(staffMember?.name, "Dounya")) {
            // Dounya a les mêmes droits que l'administrateur, sous sa propre identité.
            return (
              <AdminApp
                data={data}
                setData={setData}
                onLogout={() => setSession(null)}
                actorOverride={{ type: "staff", id: session.staffId, name: staffMember.name }}
              />
            );
          }
          return <StaffApp data={data} setData={setData} staffId={session.staffId} onLogout={() => setSession(null)} />;
        })()}
    </div>
  );
}
